package ratelimit

import (
	"errors"
	"fmt"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

// SystemClock uses the real wall clock.
type SystemClock struct{}

func (SystemClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// The bucket holds at most burst tokens and refills at rate tokens per second.
type Limiter struct {
	mu       sync.Mutex
	tokens   float64
	last     time.Time
	rate     float64 // tokens per second
	burst    float64 // bucket capacity
	clock    Clock
}

var (
	ErrNonPositiveRate  = errors.New("ratelimit: rate must be > 0")
	ErrNonPositiveBurst = errors.New("ratelimit: burst must be > 0")
	ErrNilClock         = errors.New("ratelimit: clock must not be nil")
)

// New creates a Limiter with the given refill rate (tokens/sec), burst
// capacity, and clock. The bucket starts full.
func New(rate float64, burst int, clock Clock) (*Limiter, error) {
	if clock == nil {
		return nil, ErrNilClock
	}
	if rate <= 0 {
		return nil, fmt.Errorf("%w: got %v", ErrNonPositiveRate, rate)
	}
	if burst <= 0 {
		return nil, fmt.Errorf("%w: got %v", ErrNonPositiveBurst, burst)
	}
	now := clock.Now()
	return &Limiter{
		tokens: float64(burst),
		last:   now,
		rate:   rate,
		burst:  float64(burst),
		clock:  clock,
	}, nil
}

// advance refills tokens up to the current time. Caller must hold mu.
func (l *Limiter) advance(now time.Time) {
	if now.After(l.last) {
		elapsed := now.Sub(l.last).Seconds()
		l.tokens = min(l.burst, l.tokens+elapsed*l.rate)
		l.last = now
	}
}

// AllowN reports whether n tokens may be consumed now, consuming them if so.
// n must be non-negative; a negative n returns false without side effects.
func (l *Limiter) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.clock.Now()
	l.advance(now)
	need := float64(n)
	if l.tokens >= need {
		l.tokens -= need
		return true
	}
	return false
}

// Allow reports whether a single token may be consumed now.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// Tokens returns the current number of available tokens (refilled to now).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(l.clock.Now())
	return l.tokens
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
