// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

// realClock uses the standard library.
type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// RealClock is the production clock.
var RealClock Clock = realClock{}

// Limiter is a concurrency-safe token-bucket rate limiter.
// A Limiter is safe for use by multiple goroutines simultaneously.
type Limiter struct {
	mu        sync.Mutex
	capacity  float64   // max tokens
	tokens    float64   // current tokens
	rate      float64   // tokens added per second
	last      time.Time // last refill time
	clock     Clock
}

// ErrInvalidConfig is returned by New for non-positive capacity or rate.
var ErrInvalidConfig = errors.New("ratelimit: capacity and rate must be > 0")

// New creates a Limiter with the given burst capacity and refill rate
// (tokens per second). The bucket starts full.
func New(capacity, rate float64) (*Limiter, error) {
	return NewWithClock(capacity, rate, RealClock)
}

// NewWithClock is New with an injectable clock.
func NewWithClock(capacity, rate float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 || rate <= 0 {
		return nil, ErrInvalidConfig
	}
	if clock == nil {
		clock = RealClock
	}
	return &Limiter{
		capacity: capacity,
		tokens:   capacity,
		rate:     rate,
		last:     clock.Now(),
		clock:    clock,
	}, nil
}

// Allow reports whether a single token may be consumed now.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens may be consumed at time now.
// It never blocks; if fewer than n tokens are available it returns
// false and consumes nothing.
func (l *Limiter) AllowN(n int) bool {
	return l.allowAt(l.clock.Now(), n)
}

// allowAt refills the bucket up to the given instant and attempts to
// consume n tokens. Caller must hold no lock; it locks internally.
func (l *Limiter) allowAt(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.capacity {
			l.tokens = l.capacity
		}
		l.last = now
	}

	if float64(n) > l.tokens {
		return false
	}
	l.tokens -= float64(n)
	return true
}

// Tokens returns the number of tokens currently available, refilling
// to the present instant. Useful for diagnostics and tests.
func (l *Limiter) Tokens() float64 {
	now := l.clock.Now()
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refillLocked(now)
	return l.tokens
}

// refillLocked adds tokens accrued since the last refill. Caller must hold l.mu.
func (l *Limiter) refillLocked(now time.Time) {
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.capacity {
			l.tokens = l.capacity
		}
		l.last = now
	}
}
